        );
    }

    if include_python && find_on_path("uv").is_some() {
        let uv_out = Command::new("uv")
            .args(["lock", "--check"])
            .current_dir(root)
            .output()
            .unwrap();
        assert!(
            uv_out.status.success(),
            "uv lock --check must succeed after the workspace's manifests are bumped; stderr: {}",
            String::from_utf8_lossy(&uv_out.stderr)
        );
    }
}

