        ] {
            let spec = DepSpec::WorkspaceProtocol(callisto_model::WorkspaceSpec {
                kind: callisto_model::WorkspaceKind::Pnpm,
                suffix: suffix.into(),
            });
            assert_eq!(
                coverage(&spec, &Version::semver(0, 3, 0)).unwrap(),
                expected,
                "{suffix}"
            );
        }
    }

