use std::cell::RefCell;
use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};
use std::sync::Arc;

use callisto_manifests::{Manifest, OpenContext};
#[cfg(test)]
use callisto_model::ReleaseTrigger;
use callisto_model::{
    CommandRunner, DepEdge, DepSpec, Diagnostic, DiagnosticCode, DiagnosticSeverity, Ecosystem, ManifestDecl,
    ManifestFormat, ManifestRole, Package, PackageId, PublishTarget,
};

use crate::config::resolve::{resolve_package_config, rule_applies};
use crate::config::ResolvedConfig;
use crate::error::GraphError;
use crate::identity::IdentityIndex;
use crate::locate::ProjectLocator;
use crate::manifest_cache::open_cached;

fn relative_workspace_target(root: &Path, declaring_manifest: &Path, relative: &str) -> Option<PathBuf> {
    let root = root.canonicalize().ok()?;
    let source = root.join(declaring_manifest).parent()?.canonicalize().ok()?;
    let target = source.join(relative).canonicalize().ok()?;
    if !target.starts_with(&root) {
        return None;
    }
    let relative = target.strip_prefix(&root).ok()?.to_path_buf();
    Some(relative)
}
#[allow(unused_imports)]
use crate::resolver::{DependencyResolver, ManifestWalkResolver};

/// Returns (name-scoped claiming-ecosystem set, complete unfiltered native-key list)
/// for one path's own `list` of (ecosystem, declared-id) pairs. The first is filtered
/// to entries whose declared name equals `primary_id.name()`; the second is not filtered.
fn compute_claiming_ecosystems_and_native_keys(
    list: &[(Ecosystem, PackageId)],
    primary_id: &PackageId,
) -> (BTreeSet<Ecosystem>, Vec<(Ecosystem, String)>) {
    let claiming = list
        .iter()
        .filter(|(_, id)| id.name() == primary_id.name())
        .map(|(eco, _)| *eco)
        .collect();
    let native_keys = list.iter().map(|(eco, id)| (*eco, id.name().to_string())).collect();
    (claiming, native_keys)
}

pub fn run_cascade<D: DependencyResolver>(input: CascadeInput<'_, D>) -> Result<CascadeOutcome, GraphError> {
    solve_cascade(input)
}

pub(crate) fn manifest_ecosystem(from_manifest: &std::path::Path) -> Ecosystem {
    callisto_model::ManifestFormat::from_path(from_manifest)
        .map(|fmt| fmt.ecosystem())
        .unwrap_or(Ecosystem::Npm)
}

pub(crate) fn dependency_rewrite_key(edge: &DepEdge) -> RewriteKey {
    RewriteKey {
        target: if edge.inherited {
            DepWriteTarget::CargoWorkspaceDependency {
                root_manifest: edge.from_manifest.clone(),
            }
        } else {
            DepWriteTarget::Manifest(edge.from_manifest.clone())
        },
        name: edge.name.clone(),
        kind: if edge.inherited { None } else { Some(edge.kind) },
    }
}

/// Propagates `input.seed`'s severities outward to dependents until no
/// target version changes, or `convergence_bound`'s iteration cap is
/// exceeded ([`GraphError::CascadeNotConverged`]) -- turns a would-be
/// infinite loop into a reportable bug, bound derived from package count.
///
/// One pass: pop a package, compute its bumped target, walk every
/// dependent edge, apply [`cascade_action`] to decide if that dependent's
/// severity/target changes and gets re-queued.
///
/// A genuine cross-grammar coverage failure (`coverage`'s `Err`, e.g.
/// SemVer target vs. PEP440 spec) aborts the whole cascade with
/// `Err(GraphError::GrammarMismatch)`. Soft instead: `Catalog`/`Opaque`
/// specs never have coverage tested (`coverage` returns `Unknown`
/// unconditionally), so they can't block anything -- `Catalog` gets
/// [`DiagnosticCode::CatalogSpecNotRewritten`], `Opaque` gets no
/// diagnostic. [`DiagnosticCode::RangeNotRoundTrippable`]'s real trigger
/// is a different step: [`rewrite_spec`], when a mechanical range rewrite
/// (not a coverage test) fails on an otherwise-known-coverage spec.
pub fn solve_cascade<D: DependencyResolver>(input: CascadeInput<'_, D>) -> Result<CascadeOutcome, GraphError> {
    let mut out = CascadeOutcome {
        severities: input.seed.clone(),
        reasons: input.reasons.clone(),
        ..Default::default()
    };

    for (id, &sev) in input.seed {
        let t = bump_target(id, sev, &input)?;
        out.targets.insert(id.clone(), t);
    }

    let mut worklist: BTreeSet<PackageId> = out.targets.keys().cloned().collect();
    let mut iterations = 0;
    let bound = convergence_bound(input.graph.packages().count());
    // Edges already run through rewrite_spec, so the floor-raise pass below doesn't re-diagnose them.
    let mut rewrite_attempted: BTreeSet<RewriteKey> = BTreeSet::new();

    let mut changed = true;
    while changed {
        changed = false;

        while let Some(pkg) = worklist.pop_first() {
            iterations += 1;
            if iterations > bound {
                return Err(GraphError::CascadeNotConverged { iterations });
            }

            let new_version = out.targets[&pkg].clone();
            let src_sev = out.severities[&pkg];

            let dependents: Vec<DepEdge> = input.graph.dependents_of(&pkg).cloned().collect();
            for edge in dependents {
                let cov = coverage(&edge.spec, &new_version).map_err(|source| GraphError::GrammarMismatch {
                    from: edge.from.clone(),
                    to: edge.to.clone(),
                    source,
                })?;

                let d = cascade_action(edge.kind, cov, src_sev, input.cfg);

                if d.unknown_coverage && !matches!(edge.spec, DepSpec::Opaque(_)) {
                    let code = match edge.spec {
                        DepSpec::Catalog(_) => DiagnosticCode::CatalogSpecNotRewritten,
                        _ => DiagnosticCode::RangeNotRoundTrippable,
                    };
                    out.diagnostics.push(Diagnostic {
                        code,
                        severity: DiagnosticSeverity::Warning,
                        message: format!(
                            "spec `{}` for `{}` could not be tested for coverage",
                            edge.spec.render(),
                            edge.to.display_name()
                        ),
                        package: Some(edge.from.clone()),
                        path: Some(edge.from_manifest.clone()),
                        governed_by: Some(ConfigKey::CASCADE_PRESERVE_NPM_RANGES),
                        escalated_by: None,
                    });
                }

                if d.rewrite {
                    let eco = manifest_ecosystem(&edge.from_manifest);
                    match rewrite_spec(&edge.spec, &new_version, eco, input.cfg) {
                        RewriteOutcome::Rewritten(to_spec) => {
                            let key = dependency_rewrite_key(&edge);
                            rewrite_attempted.insert(key.clone());
                            out.rewrites.insert(
                                key.clone(),
                                SpecRewrite {
                                    key,
                                    dependency: edge.to.clone(),
                                    from: edge.spec.clone(),
                                    to: to_spec,
                                },
                            );
                        }
                        RewriteOutcome::LeftAlone(dg) => {
                            rewrite_attempted.insert(dependency_rewrite_key(&edge));
                            out.diagnostics.push(dg);
                        }
                    }
                }

                let cur_sev = out.severities.get(&edge.from).copied().unwrap_or(Severity::None);
                if d.severity > cur_sev {
                    raise(
                        &edge.from,
                        d.severity,
                        &d,
                        &pkg,
                        &edge,
                        &new_version,
                        &mut out,
                        input.groups,
                        &mut worklist,
                        &input,
                    )?;
                }
            }
        }

        // Linked group release severity propagation
        for g in input.groups.linked.values() {
            let max_sev = g.max_severity(&out.severities);
            if max_sev == Severity::None {
                continue;
            }

            // A member absent from `input.base` was removed from the
            // workspace but is still listed in the group config. Skip it
            // rather than let `bump_target` below hit `MissingField` --
            // mirrors the guard `aggregate::union_fixed`/`union_linked`
            parse_npm_spec_str("catalog:", Some(WorkspaceKind::Pnpm)),
            DepSpec::Catalog(None)
        ));
        assert!(matches!(parse_npm_spec_str("workspace:^", None), DepSpec::Opaque(_)));
    }

    #[test]
    fn workspace_round_trip_only_updates_safe_out_of_range_constraints() {
        let target = Version::parse("0.3.0", VersionGrammar::SemVer).unwrap();
        for (raw, expected) in [
            ("workspace:0.2.3", "workspace:0.3.0"),
            ("workspace:^0.2.3", "workspace:^0.3.0"),
            ("workspace:~0.2.3", "workspace:~0.3.0"),
            ("workspace:@scope/lib@^0.2.3", "workspace:@scope/lib@^0.3.0"),
        ] {
            let spec = parse_npm_spec_str(raw, Some(WorkspaceKind::Pnpm));
            assert_eq!(round_trip(&spec, &target).unwrap().render(), expected);
        }
        for raw in [
            "workspace:",
            "workspace:*",
            "workspace:^",
            "workspace:~",
            "workspace:../lib",
            "workspace:@scope/lib@*",
            "workspace:^0.3.0",
            "workspace:>=0.2.0",
            "workspace:>0.2.0",
            "workspace:<0.2.0",
            "workspace:^0.2.0 || ^0.4.0",
            "catalog:tools",
            "https://example.com/lib.tgz",
        ] {
            let spec = parse_npm_spec_str(raw, Some(WorkspaceKind::Pnpm));
            assert!(round_trip(&spec, &target).is_none(), "{raw}");
        }
        let snapshot = Version::parse("0.0.0-canary.1", VersionGrammar::SemVer).unwrap();
        let spec = parse_npm_spec_str("workspace:@scope/lib@^0.2.3", Some(WorkspaceKind::Pnpm));
        assert_eq!(
            round_trip(&spec, &snapshot).unwrap().render(),
            "workspace:@scope/lib@^0.0.0-canary.1"
        );
    }

    #[test]
    fn workspace_alias_and_relative_targets_retain_declaration_keys() {
        let dir = tempdir().unwrap();
        fs::create_dir_all(dir.path().join("app")).unwrap();
        fs::create_dir_all(dir.path().join("lib")).unwrap();
        fs::write(
            dir.path().join("lib/package.json"),
            "\u{FEFF}{\"name\":\"@scope/lib\",\"version\":\"0.2.3\",\"private\":true}",
        )
        .unwrap();
        fs::write(dir.path().join("app/package.json"), r#"{
            "name":"app","version":"1.0.0","private":true,
            "dependencies":{"alias":"workspace:@scope/lib@^0.2.3","relative":"workspace:../lib","missing":"workspace:../absent"},
            "optionalDependencies":{"opt":"workspace:@scope/lib@~"},
            "peerDependencies":{"@scope/lib":"workspace:^"},
            "peerDependenciesMeta":{"@scope/lib":{"optional":true}}
        }"#).unwrap();
        let decl = ManifestDecl::new("app/package.json", ManifestRole::Canonical, ManifestFormat::PackageJson).unwrap();
        let ctx = OpenContext {
            workspace_root: dir.path(),
            cargo_workspace: None,
            npm_workspace_kind: Some(WorkspaceKind::Pnpm),
        };
        let manifest = PackageJson::open(&decl, &ctx).unwrap();
        let entries: Vec<_> = manifest.iter_dependencies().collect();
        for name in ["alias", "relative", "opt", "@scope/lib"] {
            let entry = entries.iter().find(|entry| entry.name == name).unwrap();
            assert_eq!(entry.package_name, "@scope/lib");
            assert!(matches!(entry.spec, DepSpec::WorkspaceProtocol(_)));
        }
        let missing = entries.iter().find(|entry| entry.name == "missing").unwrap();
        assert_eq!(missing.package_name, "workspace:../absent");
        assert_eq!(
            entries.iter().find(|entry| entry.name == "opt").unwrap().kind,
            DepKind::Optional
        );
        assert_eq!(
            entries.iter().find(|entry| entry.name == "@scope/lib").unwrap().kind,
            DepKind::Peer
        );
    }

